use std::{fs,io::{BufWriter,Write},path::Path,sync::Arc,time::Instant};use serde_json::json;
use zopro_prover::zopro_core::arithmetic_trace as trace;
#[path="support/perf.rs"]mod perf;
#[global_allocator]static ALLOCATOR:zopro_prover::zopro_core::alloc::Allocator=zopro_prover::zopro_core::alloc::Allocator;
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),6);let rounds:usize=args[3].parse()?;assert!([1,31].contains(&rounds));let out=Path::new(&args[4]);let enabled=match args[5].as_str(){"on"=>true,"off"=>false,_=>panic!("mode")};let f=fs::File::open(&args[1])?;let image=unsafe{memmap2::Mmap::map(&f)?};drop(f);let mut sdk=zopro_zolana::Prover::new(zopro_prover::Prover::load_image(Arc::new(image))?)?;let request=fs::read_to_string(&args[2])?;
 let mut prime_dropped=Vec::with_capacity(3);for _ in 0..3{trace::reset(enabled);std::hint::black_box(sdk.prove(&request)?);let snap=trace::snapshot();prime_dropped.push(snap.iter().map(|(_,d)|*d).sum::<u64>());}
 let mut samples=Vec::with_capacity(rounds);let mut observations=Vec::with_capacity(rounds);let mut graphs=Vec::with_capacity(3);let mut last=None;let usage0=perf::Usage::now()?;let loop_start=Instant::now();for round in 0..rounds{trace::reset(enabled);let started=Instant::now();let scope=trace::api();let proof=sdk.prove(&request)?;drop(scope);let ms=started.elapsed().as_secs_f64()*1000.;let snap=trace::snapshot();let events:usize=snap.iter().map(|(v,_)|v.len()).sum();let dropped:u64=snap.iter().map(|(_,n)|*n).sum();samples.push(ms);observations.push((round,events,dropped));if round==0||round==rounds/2||round+1==rounds{graphs.push((round,snap));}last=Some(proof);}let loop_ms=loop_start.elapsed().as_secs_f64()*1000.;let usage1=perf::Usage::now()?;fs::create_dir_all(out)?;let proof=last.unwrap();fs::write(out.join("0.proof"),&proof.proof)?;fs::write(out.join("0.public"),&proof.public_inputs)?;
 for(round,snap)in graphs{let path=out.join(format!("round{round}.events"));let mut writer=BufWriter::new(fs::File::create(&path)?);let mut lengths=Vec::new();let mut drops=Vec::new();for(events,dropped)in &snap{lengths.push(events.len());drops.push(*dropped);for event in events{for word in event{writer.write_all(&word.to_le_bytes())?;}}}writer.flush()?;println!("GRAPH {}",json!({"round":round,"file":path,"thread_lengths":lengths,"thread_dropped":drops,"record_bytes":80,"limit_per_thread":trace::LIMIT}));}
 for(round,ms)in samples.into_iter().enumerate(){println!("SAMPLE {}",json!({"round":round,"ms":ms}));}for(round,events,dropped)in observations{println!("EVENTS {}",json!({"round":round,"events":events,"dropped":dropped}));}let mut summary=usage1.difference(&usage0);summary["rounds"]=json!(rounds);summary["priming"]=json!(3);summary["workers"]=json!(rayon::current_num_threads());summary["recording"]=json!(enabled);summary["loop_wall_ms_including_observer"]=json!(loop_ms);summary["prime_dropped"]=json!(prime_dropped);println!("SUMMARY {summary}");Ok(())}
